export function canPromptInteractively(
  yes: boolean,
  dryRun: boolean,
  format: string,
  tty: boolean = process.stdin.isTTY === true && process.stderr.isTTY === true
): boolean {
  return !yes && !dryRun && format !== "json" && tty;
}

async function renderMechanical(
  edits: FixEdit[],
  dryRun: boolean,
  yes: boolean,
